index idx_tblMusic_videoId CREATE UNIQUE INDEX idx_tblMusic_videoId ON tblMusic(videoId)WHERE videoId IS NOT NULL
index idx_tblVideoMedia_videoId CREATE UNIQUE INDEX idx_tblVideoMedia_videoId ON tblVideoMedia(videoId)WHERE videoId IS NOT NULL
index ix_tblHandoutBookmarks_handout_id CREATE INDEX "ix_tblHandoutBookmarks_handout_id" ON "tblHandoutBookmarks"(handout_id)
table alembic_version CREATE TABLE alembic_version(version_num VARCHAR(32)NOT NULL,CONSTRAINT alembic_version_pkc PRIMARY KEY(version_num))
table lutGenre CREATE TABLE lutGenre(genre_id INTEGER PRIMARY KEY AUTOINCREMENT,genre TEXT,directory TEXT,active INT,orderBY INT)
table lutStatus CREATE TABLE lutStatus(pkey INTEGER PRIMARY KEY AUTOINCREMENT,status_ID INT,status TEXT)
table tblAppSettings CREATE TABLE tblAppSettings(ID INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,value TEXT,typevalue TEXT)
table tblArmorLibrary CREATE TABLE "tblArmorLibrary"(armor_lib_id INTEGER NOT NULL,api_index TEXT,name TEXT NOT NULL,armor_category TEXT,armor_class_base INTEGER,dex_bonus INTEGER,max_dex_bonus INTEGER,str_minimum INTEGER,stealth_disadvantage INTEGER,weight FLOAT,cost TEXT,properties TEXT,notes TEXT,image_url TEXT,source TEXT,game_system TEXT DEFAULT 'dnd5e',created_at TEXT NOT NULL,PRIMARY KEY(armor_lib_id),UNIQUE(api_index))
table tblBattleMapDoors CREATE TABLE "tblBattleMapDoors"(row_id INTEGER NOT NULL,map_id INTEGER NOT NULL,door_key TEXT NOT NULL,is_open INTEGER,updated_at TEXT NOT NULL,PRIMARY KEY(row_id),UNIQUE(map_id,door_key),FOREIGN KEY(map_id)REFERENCES "tblBattleMaps"(map_id))
