table tblBattleMapFloorplans CREATE TABLE "tblBattleMapFloorplans"(floorplan_id INTEGER NOT NULL,map_id INTEGER NOT NULL,json_data TEXT NOT NULL,version INTEGER,updated_at TEXT NOT NULL,PRIMARY KEY(floorplan_id),UNIQUE(map_id),FOREIGN KEY(map_id)REFERENCES "tblBattleMaps"(map_id))
table tblBattleMapNotes CREATE TABLE "tblBattleMapNotes"(note_id INTEGER NOT NULL,map_id INTEGER NOT NULL,title TEXT,body TEXT,sort_order INTEGER,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(note_id),FOREIGN KEY(map_id)REFERENCES "tblBattleMaps"(map_id))
