table tblBattleMapTokens CREATE TABLE "tblBattleMapTokens"(token_id INTEGER NOT NULL,map_id INTEGER NOT NULL,entity_type TEXT,entity_id INTEGER NOT NULL,col INTEGER,"row" INTEGER,updated_at TEXT NOT NULL,PRIMARY KEY(token_id),FOREIGN KEY(map_id)REFERENCES "tblBattleMaps"(map_id))
table tblBattleMaps CREATE TABLE "tblBattleMaps"(map_id INTEGER NOT NULL,session_id INTEGER NOT NULL,name TEXT NOT NULL,grid_cols INTEGER,grid_rows INTEGER,bg_image TEXT,is_active INTEGER,movement_scale FLOAT,sort_order INTEGER,created_at TEXT NOT NULL,PRIMARY KEY(map_id),FOREIGN KEY(session_id)REFERENCES "tblSessions"(session_id))
table tblCampaigns CREATE TABLE tblCampaigns(campaign_id INTEGER NOT NULL PRIMARY KEY,campaign_name TEXT,active INT,order_by TEXT)
table tblCharacterArmor CREATE TABLE "tblCharacterArmor"(char_armor_id INTEGER NOT NULL,character_id INTEGER NOT NULL,armor_lib_id INTEGER,armor_name TEXT NOT NULL,armor_category TEXT,armor_class_base INTEGER,dex_bonus INTEGER,max_dex_bonus INTEGER,ac_bonus INTEGER,equipped INTEGER,notes TEXT,order_by INTEGER,PRIMARY KEY(char_armor_id),FOREIGN KEY(character_id)REFERENCES "tblCharacters"(character_id),FOREIGN KEY(armor_lib_id)REFERENCES "tblArmorLibrary"(armor_lib_id))
table tblCharacterConditions CREATE TABLE tblCharacterConditions(condition_id INTEGER PRIMARY KEY AUTOINCREMENT,character_id INT NOT NULL,condition_name TEXT NOT NULL,notes TEXT DEFAULT '',created_at TEXT NOT NULL)
