table tblCharacterWeapons CREATE TABLE "tblCharacterWeapons"(char_weapon_id INTEGER NOT NULL,character_id INTEGER NOT NULL,weapon_lib_id INTEGER,weapon_name TEXT NOT NULL,weapon_category TEXT,weapon_range TEXT,damage_dice TEXT,damage_type TEXT,two_handed_damage_dice TEXT,two_handed_damage_type TEXT,range_normal INTEGER,range_long INTEGER,attack_bonus INTEGER,damage_bonus INTEGER,properties TEXT,equipped INTEGER,notes TEXT,order_by INTEGER,PRIMARY KEY(char_weapon_id),FOREIGN KEY(character_id)REFERENCES "tblCharacters"(character_id),FOREIGN KEY(weapon_lib_id)REFERENCES "tblWeaponsLibrary"(weapon_lib_id))
