table tblConditionsLibrary CREATE TABLE "tblConditionsLibrary"(condition_lib_id INTEGER NOT NULL,api_index TEXT,name TEXT NOT NULL,description TEXT,source TEXT,created_at TEXT NOT NULL,PRIMARY KEY(condition_lib_id),UNIQUE(api_index))
